<!doctypehtml><html lang="vi"><meta charset="UTF-8"><meta content="width=device-width,initial-scale=1"name="viewport"><title>404 - Lạc về thời đồ đá</title><script src="https://cdn.tailwindcss.com"></script><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;800&family=Fredoka+One&display=swap"rel="stylesheet"><style>body{font-family:Montserrat,sans-serif}.font-comic{font-family:'Fredoka One',cursive}@keyframes fadeInUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}.animate-fade-in-up{animation:.6s cubic-bezier(.16,1,.3,1) forwards fadeInUp}@keyframes swing{0%{transform:rotate(3deg)}50%{transform:rotate(-3deg)}100%{transform:rotate(3deg)}}.wire-swing{transform-origin:top center;animation:swing 4s ease-in-out infinite}@keyframes spark{0%,100%{opacity:0;transform:scale(.5) rotate(0)}20%{opacity:1;transform:scale(1.2) rotate(15deg)}40%{opacity:0;transform:scale(.8) rotate(-10deg)}60%{opacity:1;transform:scale(1.5) rotate(20deg)}80%{opacity:.2;transform:scale(.9) rotate(-5deg)}}.spark-animate{animation:spark 1.5s infinite}</style><body class="flex items-center flex-col bg-[#f4efef] h-screen justify-center overflow-hidden p-4 relative text-[#5a4e4e] w-full"><div class="absolute top-0 flex h-32 justify-center left-0 md:h-48 overflow-visible w-full"><div class="absolute top-0 wire-swing left-[30%] md:left-[40%]"><svg fill="none"viewBox="0 0 40 150"class="md:h-[200px]"height="150"width="40"><path d="M20 0 C20 50, 5 100, 25 145"stroke-linecap="round"stroke-width="12"stroke="#c97474"/><path d="M25 145 L20 155 M25 145 L28 152 M25 145 L32 150"stroke-linecap="round"stroke-width="3"stroke="#e2c7c7"/></svg><div class="absolute bottom-[-20px] left-[15px] spark-animate text-[#c97474]"><svg fill="currentColor"viewBox="0 0 24 24"height="30"width="30"><path d="M13 2L3 14H12L11 22L21 10H12L13 2Z"/></svg></div></div><div class="absolute top-0 wire-swing md:right-[40%] right-[30%]"style="animation-delay:-2s;transform-origin:top ri